do $$begin if current_setting('server_version_num')::integer<150000 then raise exception 'PostgreSQL 15+ obrigatório';end if;if to_regclass('public.erp_sales')is null or to_regclass('public.erp_financial_entries')is null or to_regclass('public.erp_stock_reservations')is null then raise exception 'M06-M08 ausente';end if;if to_regclass('public.erp_service_orders')is not null then raise exception 'Objetos M09 já existem sem histórico 0025';end if;if exists(select 1 from public.erp_permissions where key like 'services.%' and category<>'Serviços')then raise exception 'Colisão de permissões M09';end if;end$$;
